// Get original product data
const productData = $('Get Active Products').item.json;
const html = $input.item.json.data || '';

// Clean HTML aggressively
let cleanHtml = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<noscript[^>]*>[\s\S]*?<\/noscript>/gi, '')
  .replace(/<svg[^>]*>[\s\S]*?<\/svg>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&[a-z]+;/gi, ' ')
  .replace(/\s+/g, ' ')
  .trim();

if (cleanHtml.length > 8000) {
  cleanHtml = cleanHtml.substring(0, 8000);
}

// Call OpenAI API
const apiKey = $env.OPENAI_API_KEY;

const prompt = `Extract product info from this e-commerce page and return JSON:
{"price": <number or null>, "currency": "<EUR/USD/GBP or null>", "productName": "<name or null>", "inStock": <true/false/null>}

CRITICAL RULES:
1. Extract the MAIN PURCHASE PRICE - the price shown on the buy/add-to-cart button area
2. IGNORE unit prices (per piece, per unit, per kg, per 100g, etc.)
3. IGNORE shipping costs
4. IGNORE crossed-out/was prices - get the current discounted price
5. If there are multiple prices, choose the prominent checkout price, NOT the lowest
6. Price must be a number (15.99 not "15.99")
7. Return ONLY valid JSON, no markdown or explanation

Text: ${cleanHtml}`;

let openaiResult;
let errorDetail = null;

try {
  openaiResult = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/chat/completions',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`
    },
    body: {
      model: 'gpt-4o-mini',
      max_tokens: 200,
      messages: [{
        role: 'user',
        content: prompt
      }]
    },
    json: true
  });
} catch (e) {
  errorDetail = e.message;
  return {
    productId: productData.id,
    url: productData.url,
    productName: productData.productName,
    email: productData.email,
    targetPrice: parseFloat(productData.targetPrice),
    currentPrice: null,
    currency: null,
    inStock: null,
    priceFound: false,
    shouldNotify: false,
    error: errorDetail,
    htmlLength: cleanHtml.length
  };
}

// Parse OpenAI's JSON response
let extracted = { price: null, currency: null, productName: null, inStock: null };
let gptText = '';

try {
  gptText = openaiResult.choices[0].message.content.trim();
  // Remove markdown code blocks if present
  gptText = gptText.replace(/```json\n?/g, '').replace(/```\n?/g, '');
  const jsonMatch = gptText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    extracted = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // Keep defaults
}

const targetPrice = parseFloat(productData.targetPrice);
const currentPrice = typeof extracted.price === 'number' ? extracted.price : null;
const shouldNotify = currentPrice !== null && currentPrice <= targetPrice;

return {
  productId: productData.id,
  url: productData.url,
  productName: extracted.productName || productData.productName,
  email: productData.email,
  targetPrice: targetPrice,
  currentPrice: currentPrice,
  currency: extracted.currency,
  inStock: extracted.inStock,
  priceFound: currentPrice !== null,
  shouldNotify: shouldNotify,
  gptRaw: gptText
};

